import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Discord Channel Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/channels/discord.md","filePath":"integrations/channels/discord.md","lastUpdated":1790952322000}'),n={name:"integrations/channels/discord.md"};function i(s,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="discord-channel-configuration" tabindex="-1">Discord Channel Configuration <a class="header-anchor" href="#discord-channel-configuration" aria-label="Permalink to &quot;Discord Channel Configuration&quot;">​</a></h1><p>Connect your Memoh bot to Discord to join servers and chat with community members in channels and direct messages.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A Discord account with access to the <a href="https://discord.com/developers/applications" target="_blank" rel="noreferrer">Discord Developer Portal</a>.</li><li>A Discord server you can authorize the bot into.</li><li>A Memoh bot; channels are configured from its <strong>Platforms</strong> tab.</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-in-the-discord-developer-portal-create-an-application-and-get-the-bot-token" tabindex="-1">1. In the Discord Developer Portal, create an application and get the bot token <a class="header-anchor" href="#_1-in-the-discord-developer-portal-create-an-application-and-get-the-bot-token" aria-label="Permalink to &quot;1. In the Discord Developer Portal, create an application and get the bot token&quot;">​</a></h3><ol><li>Go to the <a href="https://discord.com/developers/applications" target="_blank" rel="noreferrer">Discord Developer Portal</a>.</li><li>Click <strong>New Application</strong> and give it a name.</li><li>In the left sidebar, go to <strong>Bot</strong>.</li><li>Click <strong>Reset Token</strong> to generate a <strong>Bot Token</strong>. Copy this token and store it securely.</li></ol><h3 id="_2-in-the-discord-developer-portal-enable-privileged-gateway-intents" tabindex="-1">2. In the Discord Developer Portal, enable privileged gateway intents <a class="header-anchor" href="#_2-in-the-discord-developer-portal-enable-privileged-gateway-intents" aria-label="Permalink to &quot;2. In the Discord Developer Portal, enable privileged gateway intents&quot;">​</a></h3><ol><li>On the <strong>Bot</strong> page, scroll down to the <strong>Privileged Gateway Intents</strong> section.</li><li>Enable <code>Message Content Intent</code>, <code>Server Members Intent</code> and <code>Presence Intent</code>.</li><li>Save changes.</li></ol><h3 id="_3-in-the-discord-developer-portal-invite-the-bot-to-your-server" tabindex="-1">3. In the Discord Developer Portal, invite the bot to your server <a class="header-anchor" href="#_3-in-the-discord-developer-portal-invite-the-bot-to-your-server" aria-label="Permalink to &quot;3. In the Discord Developer Portal, invite the bot to your server&quot;">​</a></h3><ol><li>Go to <strong>OAuth2</strong> &gt; <strong>URL Generator</strong>.</li><li>Select scopes: <code>bot</code>, <code>applications.commands</code>.</li><li>Select permissions: <code>Send Messages</code>, <code>Read Message History</code>, <code>Embed Links</code>, <code>Attach Files</code>.</li><li>Copy the generated URL and open it in your browser.</li><li>Select the server you want to add the bot to and authorize it.</li></ol><blockquote><p>Official guide: <a href="https://discord.com/developers/docs/intro" target="_blank" rel="noreferrer">Discord Developer Portal - Bots</a></p></blockquote><h3 id="_4-in-memoh-add-the-discord-channel" tabindex="-1">4. In Memoh, add the Discord channel <a class="header-anchor" href="#_4-in-memoh-add-the-discord-channel" aria-label="Permalink to &quot;4. In Memoh, add the Discord channel&quot;">​</a></h3><ol><li>Open your bot&#39;s detail page and go to the <strong>Platforms</strong> tab.</li><li>Click <strong>Add Channel</strong> and select <strong>Discord</strong>.</li><li>Paste the <strong>Bot Token</strong>.</li><li>Click <strong>Save and Enable</strong>.</li></ol><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Bot Token</strong></td><td>Generated with <strong>Reset Token</strong> on the application&#39;s <strong>Bot</strong> page. Store it securely.</td></tr></tbody></table><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p>Send the bot a direct message with <code>/help</code>, or @mention it in a channel of a server it has joined. If the bot replies with its command list, the channel is working.</p><h2 id="group-chats" tabindex="-1">Group chats <a class="header-anchor" href="#group-chats" aria-label="Permalink to &quot;Group chats&quot;">​</a></h2><p>Discord servers are supported. After the bot is authorized into a server, @mention it in a channel to talk to it there.</p><h2 id="disable-and-rotate-credentials" tabindex="-1">Disable and rotate credentials <a class="header-anchor" href="#disable-and-rotate-credentials" aria-label="Permalink to &quot;Disable and rotate credentials&quot;">​</a></h2><p>You can disable or remove this channel at any time from the bot&#39;s <strong>Platforms</strong> tab. To rotate the token, update the <strong>Bot Token</strong> field and save.</p>',22)])])}const b=t(n,[["render",i]]);export{g as __pageData,b as default};
